/// <reference path="../pb_data/types.d.ts" />
/**
 * A2App operation routes - GENERATED by tools/agent-app-migrate from the app's own
 * routes (agent-owned; regenerate rather than hand-edit).
 *
 * Every declared operation is served at POST /api/ops/<name> by the SAME handler
 * the app's screens call at their own path. The framework adapter has already
 * checked the caller, the arguments and (destructive) the person's approval; op()
 * answers with the protocol envelope.
 */

// POST /api/ops/journey-autocheck (ops.pb.js)
routerAdd("POST", "/api/ops/journey.autocheck", (e) => require(`${__hooks}/_a2app_impl.js`).op(e, "journey.autocheck", (ev) => ((e) => {
  const lib = require(`${__hooks}/lib_company.js`);
  if (!e.auth) return e.json(401, { error: 'Sign in required' });
  if (!e.auth.isSuperuser() && !e.auth.getBool('approved')) {
    return e.json(403, { error: 'This account is not approved yet. An owner or admin grants access on the Team page.' });
  }
  try {
    return e.json(200, lib.runAutocheck(e.app));
  } catch (err) {
    console.error('journey-autocheck failed:', err);
    return e.json(500, { error: String(err) });
  }
})(ev)));

